def greet(name: str) -> str:
    """Return a greeting message"""
    return f"Hello {name}!"

def fibonacci(n: int) -> list[int]:
    """Return first n numbers of Fibonacci sequence"""
    if n <= 0:
        return []
    elif n == 1:
        return [0]

    sequence = [0, 1]
    while len(sequence) < n:
        sequence.append(sequence[-1] + sequence[-2])
    return sequence

