def _(XLABEL, YLABEL, YLIM, alt, get_data, get_title, get_xlim, go, pio, plt):
    # Charting functions


    def mpl_view(year=1952, show_legend=True):
        data = get_data(year)
        title = get_title("Matplotlib", year)
        xlim = get_xlim(data)

        plot = plt.figure(figsize=(10, 8), facecolor=(0, 0, 0, 0))
