@app.cell
def _(compute_mandelbrot, n_max, x_offset, y_offset, zoom):
    compute_mandelbrot(n_max.value, 2., 601, 401,
                       zoom=zoom.value,
                       x_offset=x_offset.value,
                       y_offset=y_offset.value)
