        elif value == mo.ui.file:
            return [mo.ui.file(kind="button"), mo.ui.file(kind="area")]
        elif value == mo.ui.form:
            return mo.ui.text_area(placeholder="...").form()
        elif value == mo.ui.matrix:
            return mo.ui.matrix(
                [[1, 0, 0], [0, 1, 0], [0, 0, 1]],
